let root = Context::new_root(); // Scope to one tenant: realm label on Tools, then provide inside the realm.
let scoped = root.isolate::<Tools>("acme");
scoped.provide(Tools::from_static(Vec::<Arc<dyn Tool>>::new())); // Add request data on top. Isolate wins over intercept for resolution.
let request = scoped.with_intercept(TenantContext::new( "acme".to_string(), TenantTier::Pro,
)); // The realm's tool set resolves on the request context...
assert!(request.get::<Tools>().is_some());
assert!(request.get_isolated::<Tools>("acme").is_some()); // ...and stays invisible under a different label.
assert!(request.get_isolated::<Tools>("other").is_none()); Rules the tests enforce: An isolate label beats a TenantContext intercept during agent resolution (user_id_from_ctx_isolate_label_wins_over_intercept, resolver tests). Execute stays shared. It is a stateless engine; isolating it hid the root instance and broke request paths, so tenant_scope isolates Tools only. Background jobs scope with isolate alone; HTTP requests add the intercept afterward (request_tenant_ctx, same module).

