Cordis Fiber states: Inactive → Reloading → Active → Unloading plus Inertia lock to serialize transitions (Thm 63, guarded withdrawal: provider does not withdraw until dependents deactivate). Rust: pub enum FiberState { Inactive { error: Option<AppError> }, Reloading { iter: Box<dyn EffectIterator>, acc: EffectAcc, committed: CommittedView }, Active { acc: EffectAcc, committed: CommittedView }, Unloading { acc: EffectAcc, committed: CommittedView, outcome: Option<AppError> },
} pub struct Fiber { state: RwLock<FiberState>, inertia: Arc<tokio::sync::Mutex<()>>, // serialize transitions acc: Mutex<EffectAcc>, // Vec<Box<dyn FnOnce() + Send>> epoch: RwLock<String>, // computed epoch injects: CoeffectTable, committed: CommittedView, // snapshot for rollback
} impl Fiber { pub async fn refresh(&self) { let _guard = self.inertia.lock().await; // Thm 63 let new_epoch = compute_epoch(&self.injects); if *self.epoch.read() == new_epoch { return; } // no change self.reload().await; } async fn reload(&self) { /* iterate effects, recompute, commit or rollback */ } async fn dispose(self: Arc<Self>) { /* LIFO undo, state → Inactive */ }
