Cordis Events: emit / parallel / serial / bail / waterfall typed bus. Rust: #[derive(Clone, Copy, Debug)]
pub enum Dispatch { Emit, // fire-and-forget, no return, no error propagation Parallel, // tokio::JoinSet, collect all, fail-open (one handler error doesn't cancel others) Serial, // sequential, fail-open Bail, // sequential, fail-fast (first error aborts) Waterfall, // sequential, each handler receives previous handler's output (chained)
} pub struct EventsService { handlers: RwLock<HashMap<EventId, Vec<Handler>>>, // Handler = Box<dyn Fn(Value) -> Future<Output=Result<Value>> + Send> bus: broadcast::Sender<EventEnvelope>, // tokio::sync::broadcast for cross-task fan-out
} impl EventsService { pub fn on(&self, event: EventId, handler: Handler) -> Box<dyn Disposable> { self.handlers.write().entry(event).or_default().push(handler); // return Disposable that removes handler on dispose (LIFO undo) Box::new(RemoveHandler { event, idx: len - 1 }) } pub async fn dispatch(&self, event: EventId, payload: Value, mode: Dispatch) -> Result<Value> { match mode { Dispatch::Emit => { self.bus.send(envelope(payload)); Ok(Value::Null) } Dispatch::Parallel => { /* JoinSet */ } Dispatch::Serial => { /* loop */ } Dispatch::Bail => { /* loop with bail */ } Dispatch::Waterfall => { /* chain payload through handlers */ } } }
} Mapping from TS Harness (12 layers, ~60 packages), in Rust, one crate suffices; do not replicate layering ceremony. EventsService is a Service itself (ctx.provide(EventsService::new())), so any fiber can ctx.get::<EventsService>().unwrap().on(...).

